import React, { useEffect, useMemo, useRef, useState } from 'react';
import TabNav, { TabKey } from './components/TabNav';
import Accueil from './pages/Accueil';
import Apropos from './pages/Apropos';
import Realisations from './pages/Realisations';
import Contact from './pages/Contact';

function useHashTab() {
  const [tab, setTab] = useState<TabKey>(() => {
    const h = (window.location.hash.replace('#', '') as TabKey) || 'accueil';
    return (['accueil','apropos','realisations','contact'] as TabKey[]).includes(h) ? h : 'accueil';
  });

  useEffect(() => {
    const onHash = () => {
      const h = (window.location.hash.replace('#', '') as TabKey) || 'accueil';
      setTab((prev) => (prev !== h ? h : prev));
    };
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  const navigate = (t: TabKey) => {
    if (t !== tab) window.location.hash = t;
    setTab(t);
  };

  return { tab, navigate };
}

export default function App() {
  const { tab, navigate } = useHashTab();
  const sectionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    sectionRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
  }, [tab]);

  const Page = useMemo(() => {
    switch (tab) {
      case 'accueil': return <Accueil goTo={(k)=>navigate(k)} />;
      case 'apropos': return <Apropos />;
      case 'realisations': return <Realisations />;
      case 'contact': return <Contact />;
      default: return <Accueil goTo={(k)=>navigate(k)} />;
    }
  }, [tab, navigate]);

  return (
    <div className="app">
      <header className="header" role="navigation" aria-label="Navigation principale">
        <div className="container nav">
          <div className="brand">
            <div className="logo" aria-hidden="true">+</div>
            <span className="brand-name">+Propre</span>
            <span className="badge" title="Couverture Île-de-France">Service de nettoyage & d’entretien</span>
          </div>
          <TabNav active={tab} onChange={navigate} />
          <div className="quick-info">
            <a href="tel:+33765551111">📞 07&nbsp;65&nbsp;55&nbsp;11&nbsp;11</a>
            <span>•</span>
            <a href="mailto:contact@plus-propre.fr">✉️ contact@plus-propre.fr</a>
          </div>
        </div>
      </header>

      <main className="container main" ref={sectionRef}>
        {Page}
        <footer className="footer">
          <div>© {new Date().getFullYear()} +Propre — Tous droits réservés.</div>
          <div className="small">Mentions légales — Produits écoresponsables — Assurés & formés.</div>
        </footer>
      </main>
    </div>
  );
}
